DOC = ROOT / "docs" / "experiments.md"
MARKER = "<!-- Everything below this line is hand-written and kept by `dev/track.py report`. -->"
DOC_HEADER = """# Experiments

Every local run, test run and submission we record, newest first. Generated by `dev/track.py report` from
`experiments/runs.jsonl` (append-only, committed); edit only the hand-written section at the bottom.

```sh
python3 dev/track.py local [--trace PATH] [--version v1] [--note "..."]   # newest local trace by default
python3 dev/track.py platform <run_|reh_|sub_ id> [--version v1] [--note "..."]
python3 dev/track.py report                                               # rewrite this file
```

Commit is the repo HEAD when the run was recorded (`*` = uncommitted changes under `agent/`). Tokens are model
input/output tokens summed over workers (local) or as the platform reports them. Quality is the platform score
(0 to 100); local runs are not scored.
"""
DEFAULT_LEARNED = """
