    return utc_iso(dt.datetime.fromtimestamp(ms / 1000, dt.timezone.utc)) if ms else None


def git_info(commit: str | None) -> dict:
    if commit:
        return {"commit": commit, "dirty": None}

    def git(*args: str) -> str:
        return subprocess.run(["git", *args], cwd=ROOT, capture_output=True, text=True, check=True).stdout.strip()

    try:
        return {"commit": git("rev-parse", "--short", "HEAD"), "dirty": bool(git("status", "--porcelain", "--", "agent"))}
    except (OSError, subprocess.CalledProcessError):
        return {"commit": None, "dirty": None}


def agent_config() -> dict:
    try:
        config = json.loads((ROOT / "agent" / "agent.json").read_text(encoding="utf-8"))
